css:
.ll { width: min(100%, var(--w, 190px)); }
.ll img, .ll picture { display: block; width: 100%; height: auto; }
.ll__d, .ll__h { display: none; }
.ll.is-dark .ll__l { display: none; }
.ll.is-dark .ll__d { display: block; }

js:
var R=document.documentElement,mq=window.matchMedia?matchMedia('(prefers-color-scheme: dark)'):null,box=root.querySelector('.ll');if(!box)return;
var hd=root.querySelector('.ll__h img'),hi=document.querySelector('header img');
if(hd&&hi&&hi.parentNode){hd.className=hi.className;hd.removeAttribute('loading');hd.style.display='none';hi.parentNode.insertBefore(hd,hi.nextSibling)}else hd=null;
function dk(){var a=R.getAttribute('data-os-scheme');return a?a==='dark':!!(mq&&mq.matches)}
function apply(){var d=dk();box.classList.toggle('is-dark',d);if(hd){hd.style.display=d?'':'none';hi.style.display=d?'none':''}}
apply();if(mq&&mq.addEventListener)mq.addEventListener('change',apply);if(window.MutationObserver)new MutationObserver(apply).observe(R,{attributes:true,attributeFilter:['data-os-scheme']});
